        __inline__ T real() const {
            return _real;
        }

/* DPCT_ORIG         __inline__ __host__ __device__  T imag() const {*/
        __inline__ T imag() const {
            return _imag;
        }

        __inline__ complext() = default;

/* DPCT_ORIG         __inline__ __host__ __device__ complext(T real, T imag) {*/
        __inline__ complext(T real, T imag) {
            _real = real;
            _imag = imag;
        }

        __inline__ complext(const complext<T> &tmp) = default;

/* DPCT_ORIG         template<class R>
        __inline__ __host__ __device__ complext(const complext<R> &tmp) {*/
        template <class R> __inline__ complext(const complext<R>& tmp) {
            _real = tmp._real;
            _imag = tmp._imag;
        }

/* DPCT_ORIG         __inline__ __host__ __device__ complext(const std::complex<T> &tmp) {*/
        __inline__ complext(const std::complex<T>& tmp) {
            _real = tmp.real();
            _imag = tmp.imag();
        }

/* DPCT_ORIG         template<class R>
        __inline__ __host__ __device__ complext(const std::complex<R> &tmp) {*/
        template <class R> __inline__ complext(const std::complex<R>& tmp) {
            _real = tmp.real();
            _imag = tmp.imag();
        }

/* DPCT_ORIG         __inline__ __host__ __device__ complext(const T r) {*/
        __inline__ complext(const T r) {
            _real = r;
            _imag = T(0);
        }

