    void unlockSparseHandle();
    void unlockSparseHandle(int device);


  private:

    // Use the Instance() method to access the singleton
    //

    cudaDeviceManager();
    ~cudaDeviceManager();

    static void CleanUp();
    
    int _num_devices;
    std::vector<size_t> _total_global_mem; // in bytes
    std::vector<size_t> _shared_mem_per_block; // in bytes
