        cuGriddingConvolution(const vector_td<size_t, D>& matrix_size,
                              const vector_td<size_t, D>& matrix_size_os,
                              const K<REAL, D>& kernel,
                              ConvolutionType conv_type = ConvolutionType::STANDARD);

