/*
  CUDA implementation of the NFFT.

  -----------

  Accelerating the Non-equispaced Fast Fourier Transform on Commodity Graphics Hardware.
  T.S. Sørensen, T. Schaeffter, K.Ø. Noe, M.S. Hansen. 
  IEEE Transactions on Medical Imaging 2008; 27(4):538-547.

  Real-time Reconstruction of Sensitivity Encoded Radial Magnetic Resonance Imaging Using a Graphics Processing Unit.
  T.S. Sørensen, D. Atkinson, T. Schaeffter, M.S. Hansen.
  IEEE Transactions on Medical Imaging 2009; 28(12): 1974-1985. 
*/

//
// There is no header file accompanying this kernel, so it makes most sense to read the code/file from the end and upwards
//

//
// Transfer result from shared memory to global memory.
//


// Reference to shared memory
/* DPCT_ORIG extern __shared__ char _shared_mem[];*/

using namespace Gadgetron;

/* DPCT_ORIG template<class T>
__inline__ __device__
void NFFT_output(
    unsigned int number_of_samples, unsigned int number_of_batches,
    T* __restrict__ samples, unsigned int warp_size_power,
    unsigned int globalThreadId, unsigned int sharedMemFirstSampleIdx,
    bool accumulate)*/
template <class T>
__inline__ void NFFT_output(unsigned int number_of_samples, unsigned int number_of_batches, T* __restrict__ samples,
                            unsigned int warp_size_power, unsigned int globalThreadId,
                            unsigned int sharedMemFirstSampleIdx, bool accumulate)
{

    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    realType_t<T>* shared_mem = (realType_t<T>*)_shared_mem;

    for (unsigned int batch=0; batch<number_of_batches; batch++)
    {
        T sample_value;

        if constexpr (is_complex_type_v<T>)
        {
            sample_value._real =
                shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power)];
            sample_value._imag =
                /* DPCT_ORIG                 shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power) +
                   warpSize];*/
                shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power) +
                           sycl::ext::oneapi::this_work_item::get_sub_group().get_local_range().get(0)];
        }
        else
        {
            sample_value =
                shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power)];
        }

        unsigned int out_idx =
            /* DPCT_ORIG             (batch * gridDim.y + blockIdx.y) * number_of_samples + globalThreadId;*/
            (batch * item_ct1.get_group_range(1) + item_ct1.get_group(1)) * number_of_samples + globalThreadId;

        if (accumulate)
            sample_value += samples[out_idx];

        samples[out_idx] = sample_value;
    }
}

/* DPCT_ORIG template<unsigned int D>
__inline__ __device__
static void resolve_wrap(vector_td<int, D>& grid_position,
                         vector_td<unsigned int, D>& matrix_size_os)*/
template <unsigned int D>
__inline__ static void resolve_wrap(vector_td<int, D>& grid_position, vector_td<unsigned int, D>& matrix_size_os)
{
    vector_td<int, D> zero(0);
    grid_position += vector_less(grid_position, zero)*matrix_size_os;
    grid_position -= vector_greater_equal(grid_position, matrix_size_os)* matrix_size_os;
}

/* DPCT_ORIG template<class T, unsigned int D, template<class, unsigned int> class K>
__inline__ __device__
void NFFT_iterate_body(vector_td<unsigned int, D> matrix_size_os, unsigned int number_of_batches, const T * __restrict__
image, unsigned int warp_size_power, unsigned int sharedMemFirstSampleIdx, vector_td<realType_t<T>,D> sample_position,
vector_td<int,D> grid_position, const ConvolutionKernel<realType_t<T>, D, K>* kernel)*/
template <class T, unsigned int D, template <class, unsigned int> class K>
__inline__ void NFFT_iterate_body(vector_td<unsigned int, D> matrix_size_os, unsigned int number_of_batches,
                                  const T* __restrict__ image, unsigned int warp_size_power,
                                  unsigned int sharedMemFirstSampleIdx, vector_td<realType_t<T>, D> sample_position,
                                  vector_td<int, D> grid_position, const ConvolutionKernel<realType_t<T>, D, K>* kernel)
{

    using namespace thrust::cuda_cub;
      
    // Calculate the distance between current sample and the grid cell
    vector_td<realType_t<T>,D> grid_position_real = vector_td<realType_t<T>,D>(grid_position);
/* DPCT_ORIG     const vector_td<realType_t<T>,D> delta = abs(sample_position-grid_position_real);*/
    const vector_td<realType_t<T>, D> delta = sycl::fabs(sample_position - grid_position_real);

    // Compute convolution weight.
    const realType_t<T> weight = kernel->get(delta);

    // Safety measure.
    if (!isfinite(weight))
        return;

    // Resolve wrapping of grid position.
    resolve_wrap<D>(grid_position, matrix_size_os);

    realType_t<T> *shared_mem = (realType_t<T>*) _shared_mem;

/* DPCT_ORIG     unsigned int image_idx = ((blockIdx.y)*prod(matrix_size_os) + co_to_idx( vector_td<unsigned int,
 * D>(grid_position), matrix_size_os ))*number_of_batches;*/
    unsigned int image_idx =
        ((sycl::ext::oneapi::this_work_item::get_nd_item<3>().get_group(1)) * prod(matrix_size_os) +
         co_to_idx(vector_td<unsigned int, D>(grid_position), matrix_size_os)) *
        number_of_batches;

    for (unsigned int batch = 0; batch < number_of_batches; batch++)
    {
        // Read the grid cell value from global memory
        const T grid_value = cub::ThreadLoad<cub::LOAD_LDG>(image+image_idx+batch );
        
        // Add 'weight*grid_value' to the samples in shared memory
        if constexpr (is_complex_type_v<T>)
        {
            shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power)] += weight * grid_value._real;
/* DPCT_ORIG             shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power) + warpSize] += weight *
 * grid_value._imag;*/
            shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power) +
                       sycl::ext::oneapi::this_work_item::get_sub_group().get_local_range().get(0)] +=
                weight * grid_value._imag;
        }
        else
        {
            shared_mem[sharedMemFirstSampleIdx + (batch << warp_size_power)] += weight * grid_value;
        }
    }
}

