/* DPCT_ORIG template<class REAL, unsigned int D> __global__ void
write_pairs_kernel( typename uintd<D>::Type matrix_size_os, typename uintd<D>::Type matrix_size_wrap, unsigned int
num_samples_per_frame, REAL half_W, const typename reald<REAL,D>::Type * __restrict__ traj_positions, unsigned int *
__restrict__ write_offsets, unsigned int * __restrict__ tuples_first, unsigned int * __restrict__ tuples_last )*/
template <class REAL, unsigned int D>
void write_pairs_kernel(typename uintd<D>::Type matrix_size_os, typename uintd<D>::Type matrix_size_wrap,
                        unsigned int num_samples_per_frame, REAL half_W,
                        const typename reald<REAL, D>::Type* __restrict__ traj_positions,
                        unsigned int* __restrict__ write_offsets, unsigned int* __restrict__ tuples_first,
                        unsigned int* __restrict__ tuples_last)
{
    // Get sample idx
/* DPCT_ORIG     unsigned int sample_idx = blockIdx.x*blockDim.x + threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    unsigned int sample_idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);
/* DPCT_ORIG     unsigned int frame = blockIdx.y;*/
    unsigned int frame = item_ct1.get_group(1);

    if( sample_idx<num_samples_per_frame ){

        sample_idx += frame*num_samples_per_frame;
        typename reald<REAL,D>::Type p = traj_positions[sample_idx];
        output_pairs<REAL>( sample_idx, frame, p, matrix_size_os, matrix_size_wrap, half_W, write_offsets, tuples_first, tuples_last );
    }
};

template <class REAL, unsigned int D> void 
write_pairs( typename uintd<D>::Type matrix_size_os, typename uintd<D>::Type matrix_size_wrap, unsigned int num_samples_per_frame, unsigned int num_frames, REAL W, 
	     const typename reald<REAL,D>::Type * __restrict__ traj_positions, unsigned int * __restrict__ write_offsets, unsigned int * __restrict__ tuples_first, unsigned int * __restrict__ tuples_last )
{
/* DPCT_ORIG     dim3 blockDim(256);*/
    dpct::dim3 blockDim(256);
/* DPCT_ORIG     dim3 gridDim((int)ceil((double)num_samples_per_frame/(double)blockDim.x), num_frames);*/
    dpct::dim3 gridDim((int)ceil((double)num_samples_per_frame / (double)blockDim.x), num_frames);

    REAL half_W = REAL(0.5)*W;
/* DPCT_ORIG     write_pairs_kernel<REAL,D><<< gridDim, blockDim >>>
        ( matrix_size_os, matrix_size_wrap, num_samples_per_frame, half_W, traj_positions, write_offsets, tuples_first,
   tuples_last );*/
    /*
    DPCT1049:0: The work-group size passed to the SYCL kernel may exceed the limit. To get the device limit, query
    info::device::max_work_group_size. Adjust the work-group size if needed.
    */
    {
        auto exp_props = sycl::ext::oneapi::experimental::properties{sycl::ext::oneapi::experimental::use_root_sync};

        dpct::get_in_order_queue().submit([&](sycl::handler& cgh) {
            cgh.depends_on(dpct::get_current_device().get_in_order_queues_last_events());

            cgh.parallel_for<dpct_kernel_name<class write_pairs_kernel_a1e6f0, REAL, dpct_kernel_scalar<D>>>(
                sycl::nd_range<3>(gridDim * blockDim, blockDim), exp_props, [=](sycl::nd_item<3> item_ct1) {
                    write_pairs_kernel<REAL, D>(matrix_size_os, matrix_size_wrap, num_samples_per_frame, half_W,
                                                traj_positions, write_offsets, tuples_first, tuples_last);
                });
        });
    }

    CHECK_FOR_CUDA_ERROR();
}


