  // Crop
/* DPCT_ORIG   template<class T, unsigned int D> __global__ void crop_kernel
  ( vector_td<unsigned int,D> offset, vector_td<unsigned int,D> matrix_size_in, vector_td<unsigned int,D>
  matrix_size_out, const T * __restrict__ in, T * __restrict__ out, unsigned int num_batches, unsigned int num_elements
  )*/
  template <class T, unsigned int D>
  void crop_kernel(vector_td<unsigned int, D> offset, vector_td<unsigned int, D> matrix_size_in,
                   vector_td<unsigned int, D> matrix_size_out, const T* __restrict__ in, T* __restrict__ out,
                   unsigned int num_batches, unsigned int num_elements)
  {
/* DPCT_ORIG     const unsigned int idx = blockIdx.y*gridDim.x*blockDim.x + blockIdx.x*blockDim.x+threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    const unsigned int idx = item_ct1.get_group(1) * item_ct1.get_group_range(2) * item_ct1.get_local_range(2) +
                             item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);
    const unsigned int frame_offset = idx/num_elements;
    
    if( idx < num_elements*num_batches ){
      const typename uintd<D>::Type co = idx_to_co( idx-frame_offset*num_elements, matrix_size_out );
      const typename uintd<D>::Type co_os = offset + co;
      const unsigned int in_idx = co_to_idx(co_os, matrix_size_in)+frame_offset*prod(matrix_size_in);
      out[idx] = in[in_idx];
    }
  }

