/* DPCT_ORIG   template<class REAL, class T> __global__ static void
  correlation_kernel( const T * __restrict__ in, T * __restrict__ corrm, unsigned int num_batches, unsigned int
  num_elements )*/
  template <class REAL, class T>
  static void correlation_kernel(const T* __restrict__ in, T* __restrict__ corrm, unsigned int num_batches,
                                 unsigned int num_elements)
  {
/* DPCT_ORIG     const unsigned int p = blockIdx.x*blockDim.x + threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    const unsigned int p = item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);
/* DPCT_ORIG     const unsigned int i = threadIdx.y;*/
    const unsigned int i = item_ct1.get_local_id(1);

    if( p < num_elements ){
      for( unsigned int j=0; j<i; j++){
	T tmp = in[i*num_elements+p]*conj(in[j*num_elements+p]);
	corrm[(j*num_batches+i)*num_elements+p] = tmp;
	corrm[(i*num_batches+j)*num_elements+p] = conj(tmp);
      }
      T tmp = in[i*num_elements+p];
      corrm[(i*num_batches+i)*num_elements+p] = tmp*conj(tmp);
    }
  }
  
  // Build correlation matrix
  template<class T> static boost::shared_ptr< cuNDArray<T> > correlation( cuNDArray<T> *in )
  {
    typedef typename realType<T>::Type REAL;
    // Prepare internal array
    int cur_device = cudaDeviceManager::Instance()->getCurrentDevice();

    unsigned int number_of_batches = in->get_size(in->get_number_of_dimensions()-1);
    unsigned int number_of_elements = in->get_number_of_elements()/number_of_batches;

    int warp_size = cudaDeviceManager::Instance()->warp_size(cur_device);
    int max_blockdim = cudaDeviceManager::Instance()->max_blockdim(cur_device);
/* DPCT_ORIG     dim3 blockDim(((max_blockdim/number_of_batches)/warp_size)*warp_size, number_of_batches);*/
    dpct::dim3 blockDim(((max_blockdim / number_of_batches) / warp_size) * warp_size, number_of_batches);

    if( blockDim.x == 0 ){
      throw std::runtime_error("correlation: correlation dimension exceeds device capacity.");
    }

/* DPCT_ORIG     dim3 gridDim((number_of_elements+blockDim.x-1)/blockDim.x);*/
    dpct::dim3 gridDim((number_of_elements + blockDim.x - 1) / blockDim.x);

    // Invoke kernel
    std::vector<size_t> dims = in->get_dimensions(); dims.push_back(number_of_batches);
    boost::shared_ptr< cuNDArray<T> > out( new cuNDArray<T> );
    out->create(dims);

/* DPCT_ORIG     correlation_kernel<REAL,T><<< gridDim, blockDim >>>( in->get_data_ptr(), out->get_data_ptr(),
 * number_of_batches, number_of_elements );*/
    /*
    DPCT1049:27: The work-group size passed to the SYCL kernel may exceed the limit. To get the device limit, query
    info::device::max_work_group_size. Adjust the work-group size if needed.
    */
    {
        auto exp_props = sycl::ext::oneapi::experimental::properties{sycl::ext::oneapi::experimental::use_root_sync};
        dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(), {sycl::aspect::fp64});

        dpct::get_in_order_queue().submit([&](sycl::handler& cgh) {
            // helper variables defined
            auto in_get_data_ptr_ct0 = in->get_data_ptr();
            auto out_get_data_ptr_ct1 = out->get_data_ptr();

            cgh.depends_on(dpct::get_current_device().get_in_order_queues_last_events());

            cgh.parallel_for<dpct_kernel_name<class correlation_kernel_1d3480, REAL, T>>(
                sycl::nd_range<3>(gridDim * blockDim, blockDim), exp_props, [=](sycl::nd_item<3> item_ct1) {
                    correlation_kernel<REAL, T>(in_get_data_ptr_ct0, out_get_data_ptr_ct1, number_of_batches,
                                                number_of_elements);
                });
        });
    }

    CHECK_FOR_CUDA_ERROR();
    
    return out;
  }

  // Smooth correlation matrices by box filter (1D)
/* DPCT_ORIG   template<class REAL> __global__ static void
  smooth_correlation_matrices_kernel( const complext<REAL> * __restrict__ corrm, complext<REAL> * __restrict__
  corrm_smooth, intd<1>::Type image_dims )*/
  template <class REAL>
  static void smooth_correlation_matrices_kernel(const complext<REAL>* __restrict__ corrm,
                                                 complext<REAL>* __restrict__ corrm_smooth, intd<1>::Type image_dims)
  {
/* DPCT_ORIG     const int idx = blockIdx.x*blockDim.x + threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    const int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);
/* DPCT_ORIG     const int batch = blockIdx.y;*/
    const int batch = item_ct1.get_group(1);

    const int num_image_elements = prod(image_dims);

    if( idx < num_image_elements ){
    
      const int co = idx;    
      const int x = co;
    
      const int size_x = image_dims.vec[0];
    
      const REAL scale = REAL(1)/((REAL)kernel_width);
    
      complext<REAL> result = complext<REAL>(0);
    
      for (int kx = 0; kx < kernel_width; kx++) {
      
	if ((x-(kernel_width>>1)+kx) >= 0 &&
	    (x-(kernel_width>>1)+kx) < size_x)
	  {	    
	    int source_offset = 
	      batch*num_image_elements +
	      (x-(kernel_width>>1)+kx);
	  
	    result += corrm[source_offset];
	  }
      }
      corrm_smooth[batch*num_image_elements+idx] = scale*result;
    }
  }

