  // Extract CSM
/* DPCT_ORIG   template<class REAL> __global__ static void
  extract_csm_kernel( const complext<REAL> * __restrict__ corrm, complext<REAL> * __restrict__ csm, unsigned int
  num_batches, unsigned int num_elements )*/
  template <class REAL>
  static void extract_csm_kernel(const complext<REAL>* __restrict__ corrm, complext<REAL>* __restrict__ csm,
                                 unsigned int num_batches, unsigned int num_elements, char* shared_mem)
  {
/* DPCT_ORIG     const unsigned int idx = blockIdx.x*blockDim.x + threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    const unsigned int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);
/* DPCT_ORIG     const unsigned int i = threadIdx.x;*/
    const unsigned int i = item_ct1.get_local_id(2);

    if( idx < num_elements ){    
    
      // Get the dominant eigenvector for each correlation matrix.
      // Copying Peter Kellman's approach we use the power method:
      //  b_k+1 = A*b_k / ||A*b_k||
    
      complext<REAL> *data_out = (complext<REAL>*) shared_mem;
/* DPCT_ORIG       complext<REAL> *tmp_v = &(((complext<REAL>*) shared_mem)[num_batches*blockDim.x]);*/
      complext<REAL>* tmp_v = &(((complext<REAL>*)shared_mem)[num_batches * item_ct1.get_local_range(2)]);

      const unsigned int iterations = 2;
    
      for( unsigned int c=0; c<num_batches; c++){
/* DPCT_ORIG 	data_out[c*blockDim.x+i] = complext<REAL>(1);*/
        data_out[c * item_ct1.get_local_range(2) + i] = complext<REAL>(1);
      }
    
      for( unsigned int it=0; it<iterations; it++ ){
      
	for( unsigned int c=0; c<num_batches; c++){
/* DPCT_ORIG 	  tmp_v[c*blockDim.x+i] = complext<REAL>(0);*/
          tmp_v[c * item_ct1.get_local_range(2) + i] = complext<REAL>(0);
        }
      
	for( unsigned j=0; j<num_batches; j++){
	  for( unsigned int k=0; k<num_batches; k++){
/* DPCT_ORIG 	    tmp_v[j*blockDim.x+i] += corrm[(k*num_batches+j)*num_elements+idx]*data_out[k*blockDim.x+i];*/
            tmp_v[j * item_ct1.get_local_range(2) + i] +=
                corrm[(k * num_batches + j) * num_elements + idx] * data_out[k * item_ct1.get_local_range(2) + i];
          }
	}
      
	REAL tmp = REAL(0);
      
	for (unsigned int c=0; c<num_batches; c++){
/* DPCT_ORIG 	  tmp += norm(tmp_v[c*blockDim.x+i]);*/
          tmp += norm(tmp_v[c * item_ct1.get_local_range(2) + i]);
        }
      
	tmp = 1/std::sqrt(tmp);

      
	for (unsigned int c=0; c<num_batches; c++){
/* DPCT_ORIG 	  complext<REAL> res = tmp*tmp_v[c*blockDim.x+i];*/
          complext<REAL> res = tmp * tmp_v[c * item_ct1.get_local_range(2) + i];
/* DPCT_ORIG 	  data_out[c*blockDim.x+i] = res;*/
          data_out[c * item_ct1.get_local_range(2) + i] = res;
        }
      }
    
      for (unsigned int c=0; c<num_batches; c++){
/* DPCT_ORIG 	csm[c*num_elements+idx] = data_out[c*blockDim.x+i];*/
        csm[c * num_elements + idx] = data_out[c * item_ct1.get_local_range(2) + i];
      }
    }
  }

  // Extract CSM
/* DPCT_ORIG   template<class REAL> __global__ static void
  extract_csm_kernel( const complext<REAL> * __restrict__ corrm, complext<REAL> * __restrict__ csm, unsigned int
  num_batches, unsigned int num_elements, complext<REAL> * __restrict__ tmp_v )*/
  template <class REAL>
  static void extract_csm_kernel(const complext<REAL>* __restrict__ corrm, complext<REAL>* __restrict__ csm,
                                 unsigned int num_batches, unsigned int num_elements,
                                 complext<REAL>* __restrict__ tmp_v)
  {
/* DPCT_ORIG     const unsigned int idx = blockIdx.x*blockDim.x + threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    const unsigned int idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);

    if( idx < num_elements ){    
    
      // Get the dominant eigenvector for each correlation matrix.
      // Copying Peter Kellman's approach we use the power method:
      //  b_k+1 = A*b_k / ||A*b_k||
    
      const unsigned int iterations = 2;

      for( unsigned int c=0; c<num_batches; c++){
	csm[c*num_elements+idx] = complext<REAL>(1);
      }
    
      for( unsigned int it=0; it<iterations; it++ ){

	for( unsigned int c=0; c<num_batches; c++){
	  tmp_v[c*num_elements+idx] = complext<REAL>(0);
	}
      
	for( unsigned j=0; j<num_batches; j++){
	  for( unsigned int k=0; k<num_batches; k++){
	    typedef complext<REAL> T;
	    tmp_v[j*num_elements+idx] += corrm[(k*num_batches+j)*num_elements+idx]*csm[k*num_elements+idx];
	  }
	}

	REAL tmp = REAL(0);
      
	for (unsigned int c=0; c<num_batches; c++){
	  tmp += norm(tmp_v[c*num_elements+idx]);
	}
      
	tmp = 1/std::sqrt(tmp);

      
	for (unsigned int c=0; c<num_batches; c++){
	  complext<REAL> res = tmp*tmp_v[c*num_elements+idx];
	  csm[c*num_elements+idx] = res;
	}
      }
    }
  }

